from pathlib import Path
import html
R=Path('/files/onze-v2')
def header(active):
 return f'''<a class="skip" href="#main">Aller au contenu</a><header class="nav"><a class="wordmark" href="/" aria-label="Onze, accueil">onze.</a><nav class="nav-links" aria-label="Navigation principale">{''.join(f'<a href="{href}" '+('aria-current="page"' if key==active else '')+f'>{title}</a>' for key,href,title in [('home','/','Accueil'),('portfolio','/portfolio/','Portfolio'),('shop','/shop/','Shop')])}</nav><button class="nav-contact" data-contact>Parlons de votre projet ↗</button></header>'''
def footer():
 return '''<footer class="footer"><div class="footer-top"><p class="footer-title">Un projet en tête ?<br>On fait équipe.</p><button class="contact-link" data-contact>Parlons de votre projet ↗</button></div><div class="footer-bottom"><a class="wordmark" href="/" aria-label="Onze, accueil">onze.</a><p>Studio graphique · Culture football</p><nav aria-label="Navigation de pied de page"><a href="/portfolio/">Portfolio</a><a href="/shop/">Shop</a></nav></div></footer><dialog class="contact-dialog" aria-labelledby="contact-title"><button class="close-dialog" aria-label="Fermer" data-close>×</button><h2 id="contact-title">Faisons équipe.</h2><p>Ce site est une maquette. Les coordonnées du studio seront ajoutées ici avant la mise en ligne.</p><a class="text-link" href="/portfolio/">Voir le portfolio <span aria-hidden="true">↗</span></a></dialog>'''
def page(path,title,content,active,home=False):
 out=R/path;out.parent.mkdir(parents=True,exist_ok=True)
 out.write_text(f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · Onze</title><meta name="description" content="Onze, studio graphique et culture football. Identité visuelle, motion design et édition. Portfolio et shop."><meta name="theme-color" content="#101610"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/archivo.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body{' class="home"' if home else ''}>{header(active)}{content}{footer()}</body></html>''')
hero='''<main id="main"><section class="hero-track" aria-labelledby="hero-title" data-moment><div class="hero-stage"><img class="landscape" src="/assets/terrain.webp" alt="" width="2304" height="1536" fetchpriority="high"><div class="hero-copy"><h1 id="hero-title">Studio graphique.<span>Culture football.</span></h1><p>Identité visuelle, motion &amp; édition.<br>Onze joue sur tous les terrains.</p><div class="hero-links"><a class="text-link" href="/portfolio/">Voir le portfolio <span aria-hidden="true">↗</span></a><a class="text-link" href="/shop/">Voir le shop <span aria-hidden="true">↗</span></a></div></div><div class="ground-shadow" aria-hidden="true"></div><img class="ball" src="/assets/ball.webp" alt="Ballon de football patiné, animé vers la lucarne au défilement" width="900" height="900" fetchpriority="high"><img class="goal-net" src="/assets/goal-net.webp" alt="" width="2304" height="1536"><div class="scene-end"><h2>Le terrain<br>des idées.</h2><a class="text-link" href="/portfolio/">Voir les projets <span aria-hidden="true">↗</span></a></div><div class="hero-baseline"><div class="scroll-cue"><span class="scroll-line"><i></i></span><span class="scroll-label">Défiler pour jouer</span></div><span>Design × Football</span></div></div></section><section class="home-links"><div class="wrap"><h2>Sur le terrain.</h2><div class="entry-grid"><a class="entry" href="/portfolio/"><img src="/assets/project-identity.svg" alt="" loading="lazy"><strong>Le portfolio</strong><em aria-hidden="true">↗</em></a><a class="entry" href="/shop/"><img src="/assets/tee-blanc.svg" alt="" loading="lazy"><strong>Le shop</strong><em aria-hidden="true">↗</em></a></div></div></section></main>'''
page('index.html','Studio graphique & culture football',hero,'home',True)
projects=[('identite','Identité visuelle','Un club, une identité.','project-identity.svg','Identité'),('motion','Motion design','Le jeu en mouvement.','project-motion.svg','Motion'),('edition','Édition','Le football sur papier.','project-edition.svg','Édition'),('textile','Design textile','Le graphisme se porte.','project-shirt.svg','Textile')]
cards=''.join(f'''<a class="project" href="/portfolio/{slug}/" aria-label="Ouvrir la maquette {name}"><img src="/assets/{img}" alt="Étude graphique de démonstration {name}" width="1000" height="1100" loading="lazy"><div class="project-label"><div><strong>{name}</strong><small>Étude {i:02d} · Maquette</small></div><span class="arrow" aria-hidden="true">↗</span></div></a>''' for i,(slug,name,desc,img,cat) in enumerate(projects,1))
page('portfolio/index.html','Portfolio',f'''<main id="main" class="wrap"><section class="page-intro"><h1>Le portfolio.</h1><p>Identités, images et mouvements.<br>Le design avec le football en tête.</p></section><div class="notice"><span>Aperçu de la structure</span><span>4 études de démonstration</span></div><section class="grid" aria-label="Projets">{cards}</section></main>''','portfolio')
for i,(slug,name,desc,img,cat) in enumerate(projects):
 nxt=projects[(i+1)%len(projects)]
 page(f'portfolio/{slug}/index.html',name,f'''<main id="main" class="wrap"><div class="detail-head"><a class="back-link" href="/portfolio/">← Tous les projets</a><span>Étude {i+1:02d} / 04</span></div><article class="detail-hero"><div class="detail-image"><img src="/assets/{img}" alt="Maquette graphique {name}" width="1000" height="1100"></div><div class="detail-info"><span class="tag">Maquette de présentation</span><h1>{desc}</h1><p>Une étude de {name.lower()} pour présenter le futur portfolio Onze. Ce visuel sert à valider la mise en page, le rythme et la place des images.</p><p>Les réalisations et leur histoire remplaceront ces études dans la version finale.</p><dl><div><dt>Discipline</dt><dd>{cat}</dd></div><div><dt>Statut</dt><dd>Étude de démonstration</dd></div><div><dt>Studio</dt><dd>Onze</dd></div></dl></div></article><div class="next-project"><a href="/portfolio/{nxt[0]}/">Projet suivant<span aria-hidden="true">↗</span></a></div></main>''','portfolio')
locker='''<div class="locker-art" aria-hidden="true"><i></i><i></i><i></i><img src="/assets/tee-blanc.svg" alt=""></div>'''
shopcards=''.join(f'''<a class="project" href="/shop/t-shirt-{color}/"><img src="/assets/tee-{color}.svg" alt="Prototype de t-shirt Onze {color}" width="1000" height="1100" loading="lazy"><div class="project-label"><div><strong>T-shirt Onze</strong><small>{color.capitalize()} · Prototype</small></div><span class="arrow" aria-hidden="true">↗</span></div></a>''' for color in ['blanc','noir'])
page('shop/index.html','Shop',f'''<main id="main" class="wrap"><section class="page-intro"><h1>Le shop.</h1><p>Du graphisme à porter.<br>La culture foot, hors du terrain.</p></section><div class="notice"><span>Aperçu de la collection</span><span>Modèles de démonstration · Vente fermée</span></div><section class="shop-feature" aria-label="Le vestiaire">{locker}<div class="feature-copy"><h2>Le vestiaire.</h2><p>Une autre façon de voir les pièces Onze. L'espace 3D prendra place ici.</p><a class="text-link" href="/shop/vestiaire/">Ouvrir le vestiaire <span aria-hidden="true">↗</span></a></div></section><section class="grid shop-grid" aria-label="Collection">{shopcards}</section></main>''','shop')
for color in ['blanc','noir']:
 other='noir' if color=='blanc' else 'blanc'
 page(f'shop/t-shirt-{color}/index.html',f'T-shirt Onze {color}',f'''<main id="main" class="wrap"><div class="detail-head"><a class="back-link" href="/shop/">← Retour au shop</a><span>Prototype · Vente fermée</span></div><article class="detail-hero"><div class="detail-image"><img src="/assets/tee-{color}.svg" alt="Prototype de t-shirt Onze {color}" width="1000" height="1100"></div><div class="detail-info"><span class="tag">Prototype de présentation</span><h1>T-shirt Onze.</h1><p>Une pièce pour emmener le jeu ailleurs. Ce modèle présente la future fiche produit du shop.</p><div class="variants" aria-label="Couleur"><a class="text-link" href="/shop/t-shirt-{other}/">Voir en {other} <span aria-hidden="true">↗</span></a></div><p class="size-title" id="size-title">Taille <span id="chosen-size">M</span></p><div class="variants" role="group" aria-labelledby="size-title">{''.join(f'<button class="variant" data-size="{s}" aria-pressed="{str(s=="M").lower()}">{s}</button>' for s in ['S','M','L','XL'])}</div><button class="buy-state" disabled>Pièce en préparation</button><p class="preview-note">Pas de commande ni de paiement dans cette maquette. Prix, matières et disponibilités seront ajoutés avec les pièces définitives.</p><dl><div><dt>Couleur</dt><dd>{color.capitalize()}</dd></div><div><dt>Visuel</dt><dd>Prototype Onze</dd></div><div><dt>Disponibilité</dt><dd>Non commercialisé</dd></div></dl></div></article></main>''','shop')
page('shop/vestiaire/index.html','Le vestiaire',f'''<main id="main" class="wrap"><section class="vestiaire-heading"><a class="back-link" href="/shop/">← Retour au shop</a><h1>Le vestiaire.</h1><p>L'espace est prêt pour accueillir les modèles 3D du studio. Cet aperçu fixe permet de valider sa place dans le site.</p></section><section class="vestiaire" aria-label="Aperçu du vestiaire">{locker}</section><div class="next-project"><a href="/shop/t-shirt-blanc/">Voir la fiche t-shirt<span aria-hidden="true">↗</span></a></div></main>''','shop')
page('404.html','Page introuvable','<main id="main" class="wrap error-copy"><h1>Hors du terrain.</h1><p>Cette page n’existe pas.</p><a class="text-link" href="/">Retour à l’accueil <span>↗</span></a></main>','')
(R/'boutique').mkdir(exist_ok=True)
(R/'boutique/index.html').write_text('<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=/shop/"><title>Shop Onze</title></head><body><a href="/shop/">Ouvrir le shop</a></body></html>')
(R/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="#18211b"/><text x="50" y="72" text-anchor="middle" font-family="sans-serif" font-size="70" font-weight="bold" fill="#f2f1e9">o.</text></svg>')
